<?php
require 'config/koneksi.php'; require 'includes/functions.php';
if(!empty($_SESSION['siswa_id'])){header('Location: siswa/index.php');exit;}
$page_title='Daftar Akun Siswa'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $nama=trim($_POST['nama_lengkap']??''); $email=strtolower(trim($_POST['email']??'')); $hp=trim($_POST['no_whatsapp']??''); $password=$_POST['password']??''; $confirm=$_POST['konfirmasi_password']??'';
 if(!$nama||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+()\- ]{8,20}$/',$hp)||strlen($password)<8) $error='Lengkapi data dengan benar. Password minimal 8 karakter.';
 elseif($password!==$confirm) $error='Konfirmasi password tidak sama.';
 else { try{$hash=password_hash($password,PASSWORD_DEFAULT);$st=$conn->prepare('INSERT INTO akun_siswa(nama_lengkap,email,no_whatsapp,password_hash) VALUES(?,?,?,?)');$st->bind_param('ssss',$nama,$email,$hp,$hash);$st->execute();$_SESSION['flash_success']='Akun berhasil dibuat. Silakan login untuk melanjutkan pendaftaran.';header('Location: login.php');exit;}catch(mysqli_sql_exception $e){$error=$e->getCode()===1062?'Email sudah terdaftar. Silakan login atau gunakan email lain.':'Akun belum berhasil dibuat. Silakan coba kembali.';} }
}
include 'includes/header.php'; ?>
